// FlipLoop service worker (PWA pass). Makes the whole app work offline after the first visit.
// App files: precached at install, served cache-first, replaced as one versioned set.
// Google Fonts: the CSS is stale-while-revalidate, the font files (immutable URLs) cache-first.
// Drawings live in IndexedDB and never pass through here.
// The block between the markers is GENERATED by tools/build-sw-manifest.mjs. Do not edit it by hand.

// @precache-start
const VERSION = "5eb0a919ffdf";
const PRECACHE = [
  "./",
  "assets/apple-touch-icon.png",
  "assets/favicon.ico",
  "assets/favicon.svg",
  "assets/icon-192.png",
  "assets/icon-512.png",
  "assets/icon-maskable-192.png",
  "assets/icon-maskable-512.png",
  "css/style.css",
  "js/app.js",
  "js/core/challenge.js",
  "js/core/fill.js",
  "js/core/timing.js",
  "js/core/undo-ledger.js",
  "js/data/character.js",
  "js/data/lesson-copy.js",
  "js/data/lessons.js",
  "js/data/shapes.js",
  "js/data/strings.js",
  "js/data/themes.js",
  "js/editor/doc.js",
  "js/editor/drawing.js",
  "js/editor/editor.js",
  "js/editor/lesson-mode.js",
  "js/editor/panels.js",
  "js/editor/playback.js",
  "js/editor/stage.js",
  "js/editor/strip.js",
  "js/editor/undo.js",
  "js/export/gif-export.js",
  "js/export/overlay.js",
  "js/export/video-export.js",
  "js/gif/encoder.js",
  "js/lib/bus.js",
  "js/lib/busy.js",
  "js/lib/dom.js",
  "js/lib/i18n.js",
  "js/lib/raster.js",
  "js/lib/util.js",
  "js/pdf/writer.js",
  "js/print/geometry.js",
  "js/print/render.js",
  "js/pwa.js",
  "js/screens/challenge.js",
  "js/screens/common.js",
  "js/screens/gallery.js",
  "js/screens/home-art.js",
  "js/screens/home.js",
  "js/screens/lessons.js",
  "js/screens/mini-player.js",
  "js/screens/print.js",
  "js/screens/settings.js",
  "js/store/autosave.js",
  "js/store/db.js",
  "js/store/project-file.js",
  "js/store/projects.js",
  "js/store/settings.js",
  "js/store/special-projects.js",
  "js/store/storage.js",
  "js/ui/coach.js",
  "js/ui/dialog.js",
  "js/ui/icons.js",
  "js/ui/toast.js",
  "js/ui/warnings.js",
  "manifest.webmanifest"
];
const FONT_CSS = "https://fonts.googleapis.com/css2?family=Fredoka:wght@600&family=Playpen+Sans+Hebrew:wght@700&family=Rubik:wght@400;500;700&display=swap";
// @precache-end

const SHELL = `fliploop-shell-${VERSION}`;
const FONTS = "fliploop-fonts"; // survives app updates: font URLs never change content
const SCOPE = self.registration.scope;
const INDEX = new URL("./", SCOPE).href;

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(SHELL);
    // cache: "reload" skips the HTTP cache, so the set is exactly this version's files.
    await cache.addAll(PRECACHE.map((path) => new Request(new URL(path, SCOPE), { cache: "reload" })));
    await warmFonts().catch(() => {}); // best effort: offline fonts, never a reason to fail install
  })());
  // No skipWaiting here: a new version waits until the page asks for it (see js/pwa.js).
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith("fliploop-shell-") && k !== SHELL).map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});

self.addEventListener("message", (event) => {
  if (event.data?.type === "SKIP_WAITING") self.skipWaiting();
  if (event.data?.type === "GET_VERSION") event.ports[0]?.postMessage({ version: VERSION });
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin === self.location.origin) {
    if (!req.url.startsWith(SCOPE)) return;
    const isShell = url.pathname.endsWith("/") || url.pathname.endsWith("/index.html");
    if (req.mode === "navigate" && isShell) event.respondWith(fromShell(INDEX, req));
    else event.respondWith(fromShell(req, req));
    return;
  }
  if (url.hostname === "fonts.googleapis.com") event.respondWith(staleWhileRevalidate(event, req));
  else if (url.hostname === "fonts.gstatic.com") event.respondWith(cacheFirstFont(req));
});

async function fromShell(key, req) {
  // ignoreSearch: the page asks for "css/style.css?v=7"; the precache holds "css/style.css".
  const hit = await caches.match(key, { cacheName: SHELL, ignoreSearch: true });
  if (!hit) return fetch(req);
  // A host that redirected at precache time (e.g. "/app" to "/app/") leaves a redirected
  // response, which a navigation refuses: hand back a clean copy.
  return hit.redirected ? new Response(hit.body, { status: hit.status, statusText: hit.statusText, headers: hit.headers }) : hit;
}

async function staleWhileRevalidate(event, req) {
  const cache = await caches.open(FONTS);
  const hit = await cache.match(req);
  const refresh = fetch(req).then((res) => {
    if (res.ok) return cache.put(req, res.clone()).then(() => res);
    return res;
  });
  if (hit) {
    event.waitUntil(refresh.catch(() => {}));
    return hit;
  }
  return refresh;
}

async function cacheFirstFont(req) {
  const cache = await caches.open(FONTS);
  const hit = await cache.match(req);
  if (hit) return hit;
  const res = await fetch(req);
  if (res.ok) await cache.put(req, res.clone()); // CORS only: opaque entries cost ~7 MB of quota each
  return res;
}

// Caches the font CSS and its Hebrew and Latin files at install, so the first offline launch
// already has the real letterforms, even for a weight no screen has used yet.
async function warmFonts() {
  if (!FONT_CSS) return;
  const cache = await caches.open(FONTS);
  const res = await fetch(FONT_CSS, { mode: "cors", credentials: "omit" });
  if (!res.ok) return;
  await cache.put(FONT_CSS, res.clone());
  const css = await res.text();
  const urls = [...css.matchAll(/\/\*\s*(hebrew|latin)\s*\*\/[^}]*?url\((https:[^)]+)\)/g)].map((m) => m[2]);
  await Promise.all([...new Set(urls)].map(async (u) => {
    if (await cache.match(u)) return;
    const font = await fetch(u, { mode: "cors", credentials: "omit" });
    if (font.ok) await cache.put(u, font);
  }));
}
